function loadServer(){
  /* PREVIEW: there is no server, so the settings a real dashboard would read
     from /api/settings are the built-in defaults below: no password set, which
     is what a fresh install answers, and every section visible. */
  if (!SRV.sections) { SRV.sections = {}; }
  if (!SRV.passwordProtected) { SRV.passwordProtected = false; }
  if (!SRV.passwordMode) { SRV.passwordMode = ''; }
  return Promise.resolve(SRV);
}

function saveServer(){
  var secs = {};
  var boxes = document.querySelectorAll('#setsections input[data-sec-key]');
  for (var i = 0; i < boxes.length; i++) {
    secs['show_' + boxes[i].getAttribute('data-sec-key')] = boxes[i].checked;
  }
  var payload = {
    settings: {
      refresh_seconds: parseFloat(document.getElementById('setsrvrate').value),
      auto_update: document.getElementById('setautoupd').checked,
      logging: document.getElementById('setlogging').checked
    }
  };
  for (var k in secs) { payload.settings[k] = secs[k]; }
  if (SRV.passwordMode === 'partial') { payload.password = SRVPWD; }
  /* PREVIEW: there is no server to POST this to, so the answer a real one
     would give is simulated: the payload is applied to the settings the
     panel shows. */
  return Promise.resolve(payload).then(function(p){
    var s = p.settings;
    SRV.refreshSeconds = s.refresh_seconds;
    SRV.autoUpdate = s.auto_update;
    SRV.logging = s.logging;
    for (var k in s) {
      if (k.indexOf('show_') === 0) { SRV.sections[k.substring(5)] = s[k]; }
    }
    applySections();
    return SRV;
  });
}

function verifyServerPassword(pw){
  /* PREVIEW: no server behind - every password is accepted here */
  return Promise.resolve({ ok: true, applied: [] });
}

function load(){
  setConn('online', ' \u2014 PREVIEW (sample data)');
  hist = MOCK.History || [];
  render(MOCK.Current); draw();
}
